// BootSpec Boot carrier strategy (docs/06-install-pipeline.md §3). Absent → the server default (capabilities.boot_strategy_default).
type BootSpec struct {
	// EvidenceWaitSeconds Headless (protocol=none) boot stage: how long to wait for boot
	// evidence (a PXE sighting of the machine) before warning the
	// operator to power the machine on manually (docs/
	// 13-headless-design.md §4). The wait itself continues — a manual
	// power-on after the window self-heals the flow — up to the task
	// timeout. BMC-carried strategies ignore it.
	EvidenceWaitSeconds *int `json:"evidence_wait_seconds,omitempty"`

	// InstalledKernelArgs Kernel arguments persisted into the INSTALLED system's bootloader
	// (docs/04-install-spec.md §5.4): GRUB_CMDLINE_LINUX via
	// update-grub (autoinstall/preseed), bootloader --append
	// (kickstart), the agent's grub.cfg line. Needed alongside
	// kernel_args when the broken hardware misbehaves in the installed
	// system too — a nouveau-hostile GPU hangs the first boot exactly
	// like the installer until the vendor driver lands. Same token
	// rules and reserved keys as kernel_args; same windows rejection.
	InstalledKernelArgs *string `json:"installed_kernel_args,omitempty"`

	// Installer Windows-only install pathway. setup: the setup.exe flow through
	// the wimboot carrier (the default; needs the deployment SMB
	// export). agent: the agent apply-image pathway — the machine
	// boots the alpine agent, which wimlib-applies install.wim onto
	// the declarative NTFS volume; PXE-only, needs no SMB export, and
	// requires the alpine extended ISO pool
	// (MAMMOTH_WINDOWS_APPLY_ALPINE_ISO). auto: deployment-fact
	// judgment — SMB export configured → setup, absent → agent (the
	// resolution lands at prepare time). Other distros reject setup
	// or agent; auto resolves to setup only.
	Installer *BootSpecInstaller `json:"installer,omitempty"`

	// KernelArgs Extra installer-environment kernel arguments (docs/04-install-spec.md
	// §5.4), appended to the boot line the engine composes for the
	// installer kernel (both carriers: the repacked ISO's isolinux/grub
	// configs and the PXE netboot entry). The escape hatch for
	// hardware-specific boot failures no human can fix by pressing `e`
	// on an unattended machine — the canonical case: a GPU the
	// installer's nouveau driver hangs on
	// (`nomodeset modprobe.blacklist=nouveau`). Tokens are
	// whitespace-separated; each must match ^[A-Za-z0-9._,:%/+=@^~-]+$
	// (no quoting, redirection or ; — the same string is interpolated
	// into iPXE and GRUB boot lines), and keys the pipeline owns
	// (BOOTIF, ip, console, inst.ks, inst.repo, inst.syslog, auto, ds,
	// file, priority, preseed/url, seedfrom, modloop, alpine_repo,
	// apkovl, mammoth_base, modules, quiet) are rejected — their
	// engine-owned twins exist (MAMMOTH_INSTALL_CONSOLE for console).
	// windows distros reject the field (WinPE boots a BCD store, not a
	// kernel command line).
	KernelArgs *string `json:"kernel_args,omitempty"`

	// Strategy virtual_media: the builder repacks the distro ISO into a
	// per-task boot ISO the BMC mounts. pxe: the machine boots the
	// installer over the LAN (proxyDHCP + iPXE); requires the netboot
	// service enabled and a distro declaring pxe_support.
	Strategy *BootSpecStrategy `json:"strategy,omitempty"`
}

// BootSpecInstaller Windows-only install pathway. setup: the setup.exe flow through
// the wimboot carrier (the default; needs the deployment SMB
// export). agent: the agent apply-image pathway — the machine
// boots the alpine agent, which wimlib-applies install.wim onto
